import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class GeneratorResp {
    static void polecenie(OutputStream out, String... args) throws IOException {
        out.write(("*" + args.length + "\r\n").getBytes(StandardCharsets.US_ASCII));
        for (String a : args) {
            byte[] b = a.getBytes(StandardCharsets.UTF_8);
            out.write(("$" + b.length + "\r\n").getBytes(StandardCharsets.US_ASCII));
            out.write(b);
            out.write("\r\n".getBytes(StandardCharsets.US_ASCII));
        }
    }

    public static void main(String[] args) throws IOException {
        record User(String id, String name, String country, long points) {}
        List<User> users = List.of(new User("42", "Anna Maria", "PL", 1500),
                                   new User("43", "Zażółć", "PL", 980),
                                   new User("44", "Jan \"Kowal\"", "DE", 1200));
        String ns = "import:chg-1234:";
        int liczba = 0;
        try (OutputStream out = new BufferedOutputStream(Files.newOutputStream(Path.of("import.resp")))) {
            for (User u : users) {
                polecenie(out, "HSET", ns + "user:" + u.id(), "name", u.name(), "country", u.country()); liczba++;
                polecenie(out, "SADD", ns + "users:country:" + u.country(), u.id()); liczba++;
                polecenie(out, "ZADD", ns + "leaderboard", Long.toString(u.points()), u.id()); liczba++;
            }
        }
        System.out.println("polecen: " + liczba + ", bajtow: " + Files.size(Path.of("import.resp")));
    }
}

